const sites = [
  {
    name: 'بيت الريف',
    url: 'https://bietalreef.ae',
    sitemap: 'https://bietalreef.ae/sitemap.xml',
    robots: 'https://bietalreef.ae/robots.txt',
    expected_schema: ['Organization','LocalBusiness'],
    role: 'Main platform / authority hub'
  },
  {
    name: 'تطبيق بيت الريف',
    url: 'https://app.bietalreef.ae',
    sitemap: 'https://app.bietalreef.ae/sitemap.xml',
    robots: 'https://app.bietalreef.ae/robots.txt',
    expected_schema: ['SoftwareApplication','WebPage'],
    role: 'SEO support / app'
  },
  {
    name: 'وياك',
    url: 'https://weyaakai.bietalreef.ae',
    sitemap: 'https://weyaakai.bietalreef.ae/sitemap.xml',
    robots: 'https://weyaakai.bietalreef.ae/robots.txt',
    expected_schema: ['Service','FAQPage'],
    role: 'AI analysis / GEO support'
  }
];

const playbook = {
  version: 'NotebookLM MASTER SEO+AEO+GEO 2026 v1',
  weights: {
    technical_health: 30,
    core_web_vitals: 20,
    schema_structure: 20,
    aeo_geo_readiness: 30
  },
  priorities: {
    P0: [
      'domain_down',
      'accidental_noindex',
      'robots_blocks_whole_site'
    ],
    P1: [
      'lcp_over_4s',
      'missing_h1',
      'missing_canonical'
    ],
    P2: [
      'missing_alt',
      'broken_internal_link',
      'missing_expected_schema',
      'missing_direct_answer'
    ],
    P3: [
      'missing_llms_txt',
      'qa_heading_improvement',
      'ai_visibility_monitoring'
    ]
  },
  human_approval_required_for: [
    'robots.txt changes',
    'deleting content or URLs',
    'publishing content rewrites',
    'sensitive internal-link architecture changes'
  ]
};

return [{
  json: {
    sites,
    playbook,
    gsc_property: 'sc-domain:bietalreef.ae',
    run_id: 'SEO-' + new Date().toISOString().replace(/[-:.TZ]/g,'').slice(0,14),
    started_at: new Date().toISOString(),
    chatInput: `أنت المشرف التنفيذي SEO/AEO/GEO لمنظومة بيت الريف.

افحص هذه المواقع الثلاثة فقط:
${sites.map((s,i)=>`${i+1}) ${s.name}
URL: ${s.url}
robots: ${s.robots}
sitemap: ${s.sitemap}
Expected Schema: ${s.expected_schema.join(', ')}
Role: ${s.role}`).join('\n\n')}

استخدم الأدوات المتاحة للحصول على بيانات حقيقية.

المطلوب لكل نطاق:
1. تحقق من HTTP والوصول إلى الصفحة الرئيسية.
2. افحص robots.txt وتأكد أنه لا يمنع الموقع بالكامل.
3. افحص sitemap.xml وسجل هل يعمل وعدد الروابط إن أمكن.
4. افحص الصفحة الرئيسية: title, meta description, canonical, H1, headings, JSON-LD/schema, الصور وalt قدر الإمكان، والروابط الداخلية الظاهرة.
5. افحص PageSpeed على mobile وdesktop.
6. قيّم AEO: هل توجد إجابة مباشرة واضحة قرب بداية المحتوى؟ وهل بنية H2/H3 تساعد صيغة السؤال/الجواب عندما تناسب نية البحث؟
7. قيّم GEO: وضوح الكيان (الاسم، الفئة، الموقع، الخدمات) والارتباط الجغرافي.
8. تحقق من /llms.txt ولكن اعتبر غيابه P3 تجريبي فقط.
9. طبّق قواعد الأولوية والأوزان الموجودة في playbook.
10. لا تنفذ أي تعديل في الموقع. فقط فحص + توصية.
11. لا تدّعِ أن Search Console تم تحديثه. تحديث GSC يتم بعقد منفصلة بعد هذا التحليل.

أخرج JSON صالح فقط بدون Markdown بهذا الشكل:
{
  "executive_summary": "string",
  "domains": [
    {
      "name": "string",
      "url": "https://...",
      "component_scores": {
        "technical": 0,
        "cwv": 0,
        "schema": 0,
        "aeo_geo": 0
      },
      "aeo_score": 0,
      "geo_score": 0,
      "checks": {
        "http_ok": true,
        "robots_ok": true,
        "sitemap_ok": true,
        "canonical_ok": true,
        "h1_ok": true,
        "expected_schema_found": true,
        "direct_answer_ok": true,
        "qa_headings_ok": true,
        "entity_clarity_ok": true,
        "local_association_ok": true,
        "llms_txt_found": false
      },
      "pagespeed": {
        "mobile": {"performance":0,"seo":0,"lcp_ms":null},
        "desktop": {"performance":0,"seo":0,"lcp_ms":null}
      },
      "issues": [
        {
          "id": "SEO-001",
          "type": "Technical|CWV|Schema|AEO|GEO|Images|Links",
          "severity": "P0|P1|P2|P3",
          "evidence": "string",
          "recommended_fix": "string",
          "human_approval": true
        }
      ],
      "recommended_actions": {
        "P0": [],
        "P1": [],
        "P2": [],
        "P3": []
      }
    }
  ]
}`
  }
}];

const source = $('تجهيز مهمة Weyaak Supervisor').first().json;
let raw = $json.output ?? $json.text ?? $json;

if (typeof raw !== 'string') {
  raw = JSON.stringify(raw);
}

raw = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

let report;
try {
  report = JSON.parse(raw);
} catch (e) {
  report = {
    executive_summary: 'تعذر تحويل خرج الـAgent إلى JSON منظم.',
    domains: [],
    parse_error: e.message,
    raw_output: raw
  };
}

const clamp = v => Math.max(0, Math.min(100, Number(v ?? 0)));
const severityById = {
  'SEO-001':'P0',
  'SEO-002':'P0',
  'SEO-003':'P0',
  'SEO-004':'P1',
  'SEO-005':'P1',
  'CWV-001':'P1',
  'IMG-001':'P2',
  'LINK-001':'P2',
  'SCHEMA-001':'P2',
  'SCHEMA-002':'P2',
  'SCHEMA-003':'P2',
  'AEO-001':'P2',
  'AEO-002':'P3',
  'GEO-001':'P2',
  'GEO-002':'P3',
  'LLM-001':'P3'
};

const domains = Array.isArray(report.domains) ? report.domains : [];
const normalized = domains.map(d => {
  const c = d.component_scores || {};
  const technical = clamp(c.technical);
  const cwv = clamp(c.cwv);
  const schema = clamp(c.schema);
  const aeoGeo = clamp(c.aeo_geo);

  const seoScore = Math.round(
    technical * 0.30 +
    cwv * 0.20 +
    schema * 0.20 +
    aeoGeo * 0.30
  );

  const issues = (Array.isArray(d.issues) ? d.issues : []).map(issue => ({
    ...issue,
    severity: severityById[issue.id] || issue.severity || 'P3',
    human_approval:
      issue.human_approval === true ||
      /robots|delete|remove|rewrite|internal link|content/i.test(String(issue.recommended_fix || ''))
  }));

  // Enforce NotebookLM P1 rule for LCP > 4s when numeric evidence is available.
  const lcpMobile = Number(d?.pagespeed?.mobile?.lcp_ms);
  if (Number.isFinite(lcpMobile) && lcpMobile > 4000 && !issues.some(i => i.id === 'CWV-001')) {
    issues.push({
      id: 'CWV-001',
      type: 'CWV',
      severity: 'P1',
      evidence: `Mobile LCP ${lcpMobile}ms`,
      recommended_fix: 'راجع الصور الحرجة وCSS/JS ومسار التحميل لتحسين LCP.',
      human_approval: true
    });
  }

  return {
    ...d,
    component_scores: { technical, cwv, schema, aeo_geo: aeoGeo },
    seo_score: seoScore,
    aeo_score: clamp(d.aeo_score ?? aeoGeo),
    geo_score: clamp(d.geo_score ?? aeoGeo),
    issues
  };
});

const allIssues = normalized.flatMap(d => d.issues || []);
const critical = allIssues.filter(i => i.severity === 'P0').length;
const high = allIssues.filter(i => i.severity === 'P1').length;
const requiresApproval = allIssues.some(i => i.human_approval === true);

return [{
  json: {
    run_id: source.run_id,
    started_at: source.started_at,
    completed_at: new Date().toISOString(),
    gsc_property: source.gsc_property,
    playbook_version: source.playbook.version,
    executive_summary: report.executive_summary || '',
    domains: normalized,
    triage: {
      P0: critical,
      P1: high,
      requires_human_approval: requiresApproval
    },
    parse_error: report.parse_error || null
  }
}];

const report = $input.first().json;
const rows = [];

for (const domain of report.domains || []) {
  const issues = Array.isArray(domain.issues) && domain.issues.length
    ? domain.issues
    : [{
        id: 'OK-000',
        type: 'Summary',
        severity: 'P3',
        evidence: 'لم يسجل الـAgent مشكلة محددة في هذا التشغيل.',
        recommended_fix: 'استمر في المراقبة.',
        human_approval: false
      }];

  for (const issue of issues) {
    rows.push({
      json: {
        run_id: report.run_id,
        timestamp: report.completed_at,
        domain: domain.name || domain.url,
        url: domain.url,
        priority: issue.severity || 'P3',
        seo_score: domain.seo_score ?? '',
        aeo_score: domain.aeo_score ?? '',
        geo_score: domain.geo_score ?? '',
        technical_score: domain.component_scores?.technical ?? '',
        cwv_score: domain.component_scores?.cwv ?? '',
        schema_score: domain.component_scores?.schema ?? '',
        aeo_geo_readiness: domain.component_scores?.aeo_geo ?? '',
        issue_id: issue.id || '',
        issue_type: issue.type || '',
        evidence: issue.evidence || '',
        recommended_fix: issue.recommended_fix || '',
        human_approval: issue.human_approval ? 'Yes' : 'No',
        status: issue.human_approval ? 'Awaiting Approval' : 'Observed'
      }
    });
  }
}
return rows;

const report = $('تطبيق Scoring + Triage').first().json;
const sites = [
  { site_name:'بيت الريف', sitemap_url:'https://bietalreef.ae/sitemap.xml' },
  { site_name:'تطبيق بيت الريف', sitemap_url:'https://app.bietalreef.ae/sitemap.xml' },
  { site_name:'وياك', sitemap_url:'https://weyaakai.bietalreef.ae/sitemap.xml' }
];
return sites.map(s => ({
  json:{
    ...s,
    gsc_property: report.gsc_property || 'sc-domain:bietalreef.ae',
    run_id: report.run_id
  }
}));

const report = $input.first().json;
const pending = [];
for (const d of report.domains || []) {
  for (const i of d.issues || []) {
    if (i.human_approval) {
      pending.push({
        domain: d.url,
        issue_id: i.id,
        priority: i.severity,
        evidence: i.evidence,
        recommended_fix: i.recommended_fix
      });
    }
  }
}
return [{
  json: {
    run_id: report.run_id,
    requires_human_approval: pending.length > 0,
    pending_approvals: pending,
    note: pending.length
      ? 'التوصيات الحساسة لم تُنفذ تلقائيًا.'
      : 'لا توجد تعديلات حساسة مطلوبة في هذا التشغيل.'
  }
}];
